package com.primehr.security;
import com.primehr.integration.administrative.*;import org.springframework.security.access.AccessDeniedException;import org.springframework.stereotype.Component;
@Component public class LdEvaluationPermissionGuard {public static final String EVALUATION="primehr.ld-evaluation",COMPLETION_FEED="primehr.ld-completion-feed";private final AdministrativeAuthorizationClient client;public LdEvaluationPermissionGuard(AdministrativeAuthorizationClient client){this.client=client;}public PermissionDataScope require(String feature,PrimeHrAction action,String token){EffectiveFeaturePermission p=client.resolve(feature,token);boolean allowed=p.administrator()||p.canAccess()&&switch(action){case ACCESS->true;case ADD->p.canAdd();case EDIT->p.canEdit();case SUBMIT->p.canSubmit();case APPROVE->p.canApprove();default->false;};if(!allowed)throw new AccessDeniedException("L&D evaluation permission is required");PermissionDataScope scope=p.administrator()?PermissionDataScope.AGENCY_WIDE:p.dataScope();if(feature.equals(COMPLETION_FEED)&&scope!=PermissionDataScope.AGENCY_WIDE)throw new AccessDeniedException("L&D completion feed requires Agency Wide scope");return scope;}}
